JS=r'''<script>
const CLOUD_STYLE_ID='__STYLE__',CLOUD_TRIGGER='__TRIGGER__',CLOUD_PAGE_ID='__PAGE__',CLOUD_HAS_SEQUENCE=__HAS_SEQUENCE__;let cloudRunning={cloud:false,local:false};
const cloudApi=async(path,opt={})=>{const r=await fetch(path,opt);let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('HTTP '+r.status));return d};
const CREATOR_ROUTES=['/','/original-sketch','/original-graphic','/realism','/video'];function scheduleRoutePrefetch(){const connection=navigator.connection||{};if(connection.saveData||/2g/.test(connection.effectiveType||''))return;const loaded=new Set(),load=href=>{if(!CREATOR_ROUTES.includes(href)||href===location.pathname||loaded.has(href))return;loaded.add(href);const link=document.createElement('link');link.rel='prefetch';link.as='document';link.href=href;document.head.appendChild(link)};document.querySelectorAll('.topnav-link').forEach(a=>{const href=a.getAttribute('href');a.addEventListener('pointerenter',()=>load(href),{once:true});a.addEventListener('focus',()=>load(href),{once:true})});const idle=()=>CREATOR_ROUTES.filter(x=>x!==location.pathname).slice(0,2).forEach(load);'requestIdleCallback'in window?requestIdleCallback(idle,{timeout:2500}):setTimeout(idle,1800)}
const activeJobKey=backend=>'jt-active-'+CLOUD_PAGE_ID+'-'+backend;function rememberActiveJob(backend,jobId){sessionStorage.setItem(activeJobKey(backend),jobId)}function forgetActiveJob(backend){sessionStorage.removeItem(activeJobKey(backend))}
function cloudNewSeed(){return Math.floor(Math.random()*9007199254740990)+1}function cloudStripStyleTokens(t){return String(t||'').replace(/(?<![A-Za-z0-9_])jt_style\d+_v\d+(?![A-Za-z0-9_])/gi,'').replace(/(?:\s*,\s*){2,}/g,', ').replace(/^\s*,|,\s*$/g,'').trim()}function cloudSequenceMode(){if(!CLOUD_HAS_SEQUENCE)return'off';return cloudSequence.value==='3'?'sketch3':(cloudSequence.value==='4'?'sketch4':'off')}function cloudUpdateBatch(){const staged=CLOUD_HAS_SEQUENCE&&cloudSequence.value!=='off';cloudBatch.disabled=staged;if(staged)cloudBatch.value=1;cloudBatchNote.textContent=''}
const ORIGINAL_DRAWER_DEFS=[['character','角色',['character','hair','eyes','expression','interaction','species','character_inspired']],['outfit','服装',['outfit','accessory','legwear','footwear']],['pose','姿势与镜头',['prop','pose','camera']],['background','背景与剧情',['background','accent','story','theme']]];let originalOpenDrawers=new Set();
function originalEnabled(key){return typeof keyEnabledInCurrentMode==='function'?keyEnabledInCurrentMode(key):(typeof enabled==='function'?enabled(key):true)}function originalDrawerForKey(key){return ORIGINAL_DRAWER_DEFS.find(d=>d[2].includes(key))?.[0]}function restoreOriginalOpenDrawers(snapshotState){originalOpenDrawers=new Set(Object.keys(snapshotState||{}).map(originalDrawerForKey).filter(Boolean))}
function renderOriginalWorkbench(){if(!document.getElementById('originalDrawers'))return;originalModeOriginal.classList.toggle('active',currentMode==='original');originalModeCharacter.classList.toggle('active',currentMode==='character');const root=originalDrawers;root.innerHTML='';ORIGINAL_DRAWER_DEFS.forEach(([key,title,keys])=>{const visible=keys.filter(k=>POOLS[k]&&originalEnabled(k));if(!visible.length)return;const section=document.createElement('section');section.className='original-drawer'+(originalOpenDrawers.has(key)?' open':'');section.dataset.originalDrawer=key;section.innerHTML=`<button class="original-drawer-head"><span>${title}</span><span>⌄</span></button><div class="original-drawer-body"></div>`;section.querySelector('.original-drawer-head').onclick=()=>{originalOpenDrawers.has(key)?originalOpenDrawers.delete(key):originalOpenDrawers.add(key);renderOriginalWorkbench()};const body=section.querySelector('.original-drawer-body');visible.forEach(k=>{const current=Math.max(0,POOLS[k].findIndex(v=>state[k]&&v[1]===state[k][1]));const item=document.createElement('article');item.className='original-item';item.innerHTML=`<div class="original-item-head"><span class="original-item-name">${LABELS[k]||k}</span><span class="original-item-actions"><button class="original-reroll" aria-label="随机${LABELS[k]||k}">↻</button><button class="original-lock" aria-label="${locked[k]?'解锁':'锁定'}${LABELS[k]||k}">${locked[k]?'🔒':'🔓'}</button></span></div><select class="original-picker">${POOLS[k].map((v,i)=>`<option value="${i}" ${i===current?'selected':''}>${v[0]}</option>`).join('')}</select>`;item.querySelector('.original-picker').onchange=e=>{state[k]=POOLS[k][+e.target.value];save();render()};item.querySelector('.original-reroll').onclick=()=>{state[k]=pick(POOLS[k]);save();render()};item.querySelector('.original-lock').onclick=()=>{locked[k]=!locked[k];save();render()};body.appendChild(item)});root.appendChild(section)});originalPromptText.value=buildAll()}
render=function(){updateModeUI();const legacyGrid=document.getElementById('grid');if(legacyGrid)legacyGrid.replaceChildren();const legacyPrompt=document.getElementById('promptText');if(legacyPrompt)legacyPrompt.value=buildAll();renderOriginalWorkbench()};
function importGeneratedPromptToManual(){manualPositive.value=cloudStripStyleTokens(buildPositive());manualNegative.value=NEGATIVE;cloudPromptMode.value='manual';cloudManualPanel.classList.add('open');manualPositive.focus()}function updateCloudPromptMode(){cloudManualPanel.classList.toggle('open',cloudPromptMode.value==='manual')}
const LIQUID_POLL_INTERVAL=800,LIQUID_MIN_DURATION=260,LIQUID_MAX_DURATION=1800,LIQUID_REDUCED_MOTION=matchMedia('(prefers-reduced-motion: reduce)').matches,liquidMotionState=new WeakMap();
function paintLiquid(b,value){const pct=Math.max(0,Math.min(100,value));b.style.setProperty('--liquid-progress',pct.toFixed(2)+'%');b.querySelectorAll('.liquid-percent').forEach(l=>l.textContent=Math.round(pct)+'%')}function renderLiquidFrame(b,now){const state=liquidMotionState.get(b);if(!state)return;const elapsed=Math.max(0,now-state.started),t=Math.min(1,elapsed/state.duration),smooth=t*t*(3-2*t);state.display=Math.min(state.target,state.from+(state.target-state.from)*smooth);paintLiquid(b,state.display);if(t<1&&state.display<state.target)state.raf=requestAnimationFrame(ts=>renderLiquidFrame(b,ts));else{state.display=state.target;state.raf=0;paintLiquid(b,state.display);b.dispatchEvent(new CustomEvent('liquidsettled',{detail:{progress:state.display}}))}}function setLiquidProgress(b,progress,immediate=false){const target=Math.max(0,Math.min(100,Number(progress)||0));let state=liquidMotionState.get(b);if(!state){state={display:0,target:0,from:0,started:0,duration:LIQUID_MIN_DURATION,raf:0};liquidMotionState.set(b,state)}if(state.raf)cancelAnimationFrame(state.raf);state.target=Math.max(state.display,target);b.dataset.progressTarget=state.target.toFixed(2);state.from=state.display;const distance=Math.abs(target-state.display);state.duration=Math.min(LIQUID_MAX_DURATION,Math.max(LIQUID_MIN_DURATION,distance*28));state.started=performance.now();if(immediate||LIQUID_REDUCED_MOTION){state.display=state.target;state.raf=0;paintLiquid(b,state.display);return}state.raf=requestAnimationFrame(ts=>renderLiquidFrame(b,ts))}function waitLiquidSettled(b,target,timeout=LIQUID_MAX_DURATION+500){const state=liquidMotionState.get(b);if(!state||state.display>=target-.05)return Promise.resolve();return new Promise(resolve=>{let done=false;const finish=()=>{if(done)return;done=true;b.removeEventListener('liquidsettled',onSettle);resolve()};const onSettle=e=>{if(e.detail.progress>=target-.05)finish()};b.addEventListener('liquidsettled',onSettle);setTimeout(finish,timeout)})}function setLiquidLoading(b,on){b.classList.toggle('is-loading',on);b.setAttribute('aria-busy',on?'true':'false');if(!on){const state=liquidMotionState.get(b);if(state?.raf)cancelAnimationFrame(state.raf);liquidMotionState.delete(b);paintLiquid(b,0);b.dataset.progressTarget='0'}}function setResultTab(b){document.querySelectorAll('[data-result-tab]').forEach(x=>x.classList.toggle('active',x.dataset.resultTab===b));document.querySelectorAll('[data-result-panel]').forEach(x=>x.classList.toggle('active',x.dataset.resultPanel===b))}async function pollJobResilient(jobId,onUpdate,maxConsecutive=6){let retry=0;while(1){await new Promise(x=>setTimeout(x,LIQUID_POLL_INTERVAL));try{const j=await cloudApi('/api/job/'+jobId);retry=0;onUpdate(j,false,0);if(j.status==='done'||j.status==='error')return j}catch(e){retry++;onUpdate(null,true,retry);if(retry>=maxConsecutive)throw new Error('连续'+retry+'次轮询失败：'+e.message)}}}async function submitGenerateResilient(body){let last;for(let retry=0;retry<2;retry++){try{return await cloudApi('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}catch(e){last=e;if(retry===0)await new Promise(x=>setTimeout(x,1600))}}throw last}
function cloudSnapshot(backend){return{source_page:CLOUD_PAGE_ID,style:CLOUD_STYLE_ID,mode:currentMode,state:JSON.parse(JSON.stringify(state)),locked:JSON.parse(JSON.stringify(locked)),trigger_input:document.getElementById('triggerInput')?.value||'',prefix_input:document.getElementById('prefixInput')?.value||'',width:+cloudW.value,height:+cloudH.value,batch:+cloudBatch.value,hd:+cloudHd.value,sequence_mode:cloudSequenceMode(),prompt_mode:cloudPromptMode.value,manual_positive:manualPositive.value,manual_negative:manualNegative.value,seed:+cloudSeed.value,seed_mode:cloudSeedMode.value,generation_backend:backend}}
function cloudApplySnapshot(s){if(!s||s.source_page!==CLOUD_PAGE_ID||!s.state)return;state=JSON.parse(JSON.stringify(s.state));locked=JSON.parse(JSON.stringify(s.locked||{}));currentMode=s.mode||'original';restoreOriginalOpenDrawers(s.state);if(document.getElementById('triggerInput'))triggerInput.value=s.trigger_input||'';if(document.getElementById('prefixInput'))prefixInput.value=s.prefix_input||'';cloudW.value=s.width||768;cloudH.value=s.height||1024;cloudBatch.value=s.batch||1;cloudHd.value=s.hd||0;cloudSeed.value=s.seed||cloudNewSeed();cloudSeedMode.value=s.seed_mode||'fixed';cloudPromptMode.value=s.prompt_mode||'options';manualPositive.value=s.manual_positive||'';manualNegative.value=s.manual_negative||'';if(CLOUD_HAS_SEQUENCE)cloudSequence.value=s.sequence_mode==='sketch3'?'3':(s.sequence_mode==='sketch4'?'4':'off');save();render();cloudUpdateBatch();updateCloudPromptMode();cloudFavOverlay.classList.remove('open')}
function cloudCoinText(j){if(j.generation_backend==='local')return'RH币：不适用';if(j.rh_coins!==null&&j.rh_coins!==undefined&&j.rh_coins!=='')return'RH币：'+String(j.rh_coins);return(j.status==='done'||j.status==='error')?'RH币：未返回':'RH币：统计中'}
function cloudAddResult(j,c){c.innerHTML='';if((j.images||[]).length){previewEmpty.classList.add('hidden');document.querySelector('.preview-stage').classList.add('has-results')}setResultTab(j.generation_backend==='local'?'local':'cloud');(j.images||[]).forEach((im,i)=>{const x=document.createElement('div');x.className='cloud-job';x.innerHTML=`${im.stage_label?`<b>${im.stage_label}</b>`:''}<div class="cloud-note">${j.generation_backend==='local'?'本地':'云端'} · ${cloudCoinText(j)} · 种子 ${j.seed??'未知'}</div><img loading="lazy" decoding="async" src="${im.preview_url||im.url}"><button class="cloud-dl cloud-fav">♥ 收藏</button><a class="cloud-dl" target="_blank" href="${im.url}">下载原图</a>`;x.querySelector('.cloud-fav').onclick=async e=>{e.target.disabled=true;try{await cloudApi('/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:j.id,image_index:i})});e.target.textContent='✓ 已收藏'}catch(err){e.target.disabled=false;e.target.textContent='收藏失败'};};c.appendChild(x)})}
async function resumeActiveJob(backend){const jobId=sessionStorage.getItem(activeJobKey(backend));if(!jobId)return;const b=backend==='local'?cloudGenerateLocal:cloudGenerateCloud,s=backend==='local'?cloudStatusLocal:cloudStatusCloud,r=backend==='local'?cloudResultLocal:cloudResultCloud;try{let j=await cloudApi('/api/job/'+jobId);if(j.status==='done'){forgetActiveJob(backend);cloudAddResult(j,r);s.textContent='✓ 已恢复完成任务（'+j.elapsed+'秒）';return}if(j.status==='error'){forgetActiveJob(backend);s.textContent='✗ '+(j.error||'任务失败');return}cloudRunning[backend]=true;b.disabled=true;setLiquidLoading(b,true);setLiquidProgress(b,Number(j.progress_pct)||0);s.textContent='正在恢复任务 '+Math.round(Number(j.progress_pct)||0)+'%';j=await pollJobResilient(jobId,next=>{if(!next)return;setLiquidProgress(b,Number(next.progress_pct)||0);s.textContent=(next.provider_status||next.status)+' '+Math.round(Number(next.progress_pct)||0)+'%'});forgetActiveJob(backend);if(j.status==='done'){setLiquidProgress(b,100);cloudAddResult(j,r);await waitLiquidSettled(b,100);s.textContent='✓ 完成（'+j.elapsed+'秒）'}else s.textContent='✗ '+(j.error||'任务失败')}catch(e){s.textContent='任务恢复暂时失败：'+e.message}finally{cloudRunning[backend]=false;setLiquidLoading(b,false);b.disabled=false}}async function resumeActiveJobs(){await Promise.all(['cloud','local'].map(resumeActiveJob))}
async function cloudGenerateNow(backend){if(cloudRunning[backend])return;cloudRunning[backend]=true;const b=backend==='local'?cloudGenerateLocal:cloudGenerateCloud,s=backend==='local'?cloudStatusLocal:cloudStatusCloud,r=backend==='local'?cloudResultLocal:cloudResultCloud;let lastProgress=0,terminal=false;b.disabled=true;setLiquidLoading(b,true);setLiquidProgress(b,3);s.textContent='正在提交…';r.innerHTML='';try{if(cloudSeedMode.value==='random')cloudSeed.value=cloudNewSeed();const positive=cloudPromptMode.value==='manual'?manualPositive.value.trim():cloudStripStyleTokens(buildPositive()),negative=cloudPromptMode.value==='manual'?manualNegative.value.trim():NEGATIVE;if(!positive)throw new Error('正向提示词不能为空');const client_request_id=backend+'-'+Date.now()+'-'+Math.random().toString(36).slice(2);const body={workflow:'anima02',prompt:positive,negative_prompt:negative,prompt_mode:cloudPromptMode.value,width:+cloudW.value,height:+cloudH.value,batch:+cloudBatch.value,hd:+cloudHd.value,seed:+cloudSeed.value,seed_mode:cloudSeedMode.value,style_id:CLOUD_STYLE_ID,mode:currentMode,sequence_mode:cloudSequenceMode(),generation_backend:backend,client_request_id,selection_snapshot:cloudSnapshot(backend)};const q=await submitGenerateResilient(body);rememberActiveJob(backend,q.job_id);const j=await pollJobResilient(q.job_id,(next,broken,retry)=>{if(broken){s.textContent='轮询连接暂时中断，正在重试（'+retry+'/6）';return}lastProgress=Math.max(lastProgress,Number(next.progress_pct)||0);setLiquidProgress(b,lastProgress);const phase=next.provider_status==='RESULT_TRANSFERRING'||next.provider_status==='RESULT_DOWNLOADING'?'正在取回结果 '+(next.transfer_index||0)+'/'+(next.transfer_total||0):(next.provider_status||next.status);s.textContent=phase+' '+Math.round(lastProgress)+'%'});terminal=true;forgetActiveJob(backend);if(j.status==='error')throw new Error(j.error||'生成失败');setLiquidProgress(b,100);cloudAddResult(j,r);await waitLiquidSettled(b,100);s.textContent='✓ 完成（'+j.elapsed+'秒）';await new Promise(x=>setTimeout(x,420))}catch(e){s.textContent='✗ '+e.message;if(terminal)forgetActiveJob(backend)}finally{cloudRunning[backend]=false;setLiquidLoading(b,false);b.disabled=false}}
async function cloudHistory(){cloudHistList.innerHTML='加载中…';try{const a=await cloudApi('/api/jobs');cloudHistList.innerHTML='';a.filter(j=>j.style_id===CLOUD_STYLE_ID).forEach(j=>{const d=document.createElement('div');d.className='cloud-job';d.innerHTML=`<b>${j.generation_backend==='local'?'本地':'云端'} · ${j.status}</b><div class="cloud-note">种子 ${j.seed??'未知'} · ${cloudCoinText(j)} · ${j.elapsed||''}秒</div><button class="cloud-dl">查看</button>`;d.querySelector('button').onclick=()=>cloudAddResult(j,d);cloudHistList.appendChild(d)})}catch(e){cloudHistList.textContent='历史加载失败'}}async function cloudFavorites(){cloudFavList.innerHTML='加载中…';try{const a=await cloudApi('/api/favorites');cloudFavList.innerHTML='';a.filter(f=>f.selection_snapshot?.source_page===CLOUD_PAGE_ID).forEach(f=>{const d=document.createElement('div');d.className='cloud-job';d.innerHTML=`<img loading="lazy" src="${f.preview_url||f.image_url}"><button class="cloud-dl cloud-apply">套用提示词、选项和种子</button><a class="cloud-dl" target="_blank" href="${f.image_url}">下载</a>`;d.querySelector('.cloud-apply').onclick=()=>cloudApplySnapshot(f.selection_snapshot);cloudFavList.appendChild(d)})}catch(e){cloudFavList.textContent='收藏加载失败'}}
originalModeOriginal.onclick=()=>{currentMode='original';originalOpenDrawers.clear();save();render()};originalModeCharacter.onclick=()=>{currentMode='character';if(!state.character_inspired&&POOLS.character_inspired)state.character_inspired=POOLS.character_inspired[0];originalOpenDrawers.clear();save();render()};originalRandomAll.onclick=()=>{randomize(false)};originalClearAll.onclick=()=>{locked={};originalOpenDrawers.clear();save();render()};originalPromptToggle.onclick=()=>originalPrompt.classList.toggle('open');
cloudGenerateCloud.onclick=()=>cloudGenerateNow('cloud');cloudGenerateLocal.onclick=()=>cloudGenerateNow('local');importGeneratedPrompt.onclick=importGeneratedPromptToManual;cloudPromptMode.onchange=updateCloudPromptMode;cloudSeedMode.onchange=()=>{if(cloudSeedMode.value==='random')cloudSeed.value=cloudNewSeed()};if(CLOUD_HAS_SEQUENCE)cloudSequence.onchange=cloudUpdateBatch;document.querySelectorAll('[data-result-tab]').forEach(x=>x.onclick=()=>setResultTab(x.dataset.resultTab));cloudHistOpen.onclick=()=>{cloudHistOverlay.querySelector('.library-scroll').scrollTop=0;cloudHistOverlay.classList.add('open');cloudHistory()};cloudFavOpen.onclick=()=>{cloudFavOverlay.querySelector('.library-scroll').scrollTop=0;cloudFavOverlay.classList.add('open');cloudFavorites()};document.querySelectorAll('.library-overlay .cloud-close').forEach(b=>b.onclick=()=>b.closest('.library-overlay').classList.remove('open'));cloudSeed.value=cloudNewSeed();cloudUpdateBatch();updateCloudPromptMode();setResultTab('cloud');render();scheduleRoutePrefetch();resumeActiveJobs();
</script>'''

def build(source_name,out_name,style,trigger,page_id,has_sequence,active):
 src=(ATT/source_name).read_text(encoding='utf8');seq='<label>铅绘分步<select id="cloudSequence"><option value="off">关闭</option><option value="3">3步</option><option value="4">4步</option></select></label>' if has_sequence else '<select id="cloudSequence" style="display:none"><option value="off">关闭</option></select>'
 top=TOPBAR.replace('__SKETCH_ACTIVE__','active' if active=='sketch' else '').replace('__GRAPHIC_ACTIVE__','active' if active=='graphic' else '')
 heading='<div class="pane-heading original-heading"><div><span class="eyebrow">'+('ORIGINAL SKETCH' if active=='sketch' else 'ORIGINAL GRAPHIC')+'</span><h1>创作设置</h1></div></div>'
 src=src.replace('</style>',SHARED_CSS+'\n</style>',1).replace('<body>','<body><div class="app-shell">'+top+'<main class="studio-grid"><aside class="creation-pane"><div class="creation-scroll">'+heading+ORIGINAL_WORKBENCH,1).replace('<main class="wrap">','<div class="wrap original-content">',1)
 src=src.replace('</main>','</div>'+UI_BASE.replace('__SEQUENCE__',seq)+FOOTER+PREVIEW+OVERLAYS,1)
 script=JS.replace('__STYLE__',style).replace('__TRIGGER__',trigger).replace('__PAGE__',page_id).replace('__HAS_SEQUENCE__','true' if has_sequence else 'false')
 src=src.replace('</body>',script+'</div></body>',1);(STATIC/out_name).write_text(src,encoding='utf8');print(out_name,len(src))

build('sketch_anime_dual_mode_generator (1).html','original_sketch.html','sketch','jt_style1_v1','original_sketch',True,'sketch')
build('graphic_anime_style2_dual_mode_generator (1).html','original_graphic.html','graphic','jt_style2_v1','original_graphic',False,'graphic')
